#!/usr/bin/env python3
"""Render the self-contained review from its frozen, sanitized evidence JSON."""
import collections
import html
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
D = json.loads((HERE / 'report-data.json').read_text())
F = D['findings']
COUNTS = collections.Counter(f['severity'] for f in F)
esc = lambda x: html.escape(str(x), quote=True)


def paras(value):
    if isinstance(value, list):
        return '<ul>' + ''.join('<li>' + esc(x) + '</li>' for x in value) + '</ul>'
    return '<p>' + esc(value) + '</p>'


def sources(f):
    return ' '.join(f'<a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">{esc(s["title"])} ↗</a>' for s in f.get('sources', []))


def evidence(f):
    out = []
    for e in f.get('evidence', []):
        label = e['file'] + (':' + str(e['line']) if e.get('line') else '')
        excerpt = f'<pre><code>{esc(e["excerpt"])}</code></pre>' if e.get('excerpt') else ''
        if excerpt:
            out.append(f'<details class="evidence"><summary><code>{esc(label)}</code></summary><p>{esc(e["detail"])}</p>{excerpt}</details>')
        else:
            out.append(f'<div class="evidence observed"><code>{esc(label)}</code><p>{esc(e["detail"])}</p></div>')
    return ''.join(out)


def card(f):
    ident = esc(f['id'])
    trigger = f'<p class="trigger">Trigger: {esc(f["trigger"])}</p>' if f.get('trigger') else ''
    return f'''<article class="finding" id="{ident}" data-id="{ident}" data-priority="{esc(f['severity'])}" data-group="{esc(f['group'])}" data-lens="{esc(f['lens'])}">
      <div class="finding-meta"><span class="badge {esc(f['severity'])}">{esc(f['severity'])}</span><span class="mono">{ident}</span><span>{esc(f['group'])}</span><span class="lens">{esc(f['lens'])}</span></div>
      <h3><a class="permalink" href="#{ident}">{esc(f['title'])}</a></h3>{trigger}
      <p class="summary">{esc(f['summary'])}</p>
      <details class="finding-detail"><summary>Evidence, recommendation & verification <span aria-hidden="true">↗</span></summary>
        <div class="detail-body"><div class="confidence"><b>Evidence classification</b> {esc(f['kind'])}<br><b>Confidence</b> {esc(f['confidence'])}</div>
        <h4>Why it matters</h4>{paras(f['impact'])}
        <div class="recommendation"><h4>Recommendation</h4>{paras(f['recommendation'])}</div>
        <h4>What was checked / how to verify a change</h4>{paras(f['validation'])}
        <h4>Evidence</h4>{evidence(f)}
        {('<div class="sources"><b>Primary references</b><br>' + sources(f) + '</div>') if f.get('sources') else ''}
        <div class="decision-box"><label for="decision-{ident}">Your decision</label><select id="decision-{ident}" class="decision" data-for="{ident}"><option value="unreviewed">Not reviewed</option><option value="fix">Plan a change</option><option value="investigate">Investigate / measure</option><option value="keep">Keep current choice</option><option value="defer">Defer</option></select><label for="note-{ident}">Private review note</label><textarea id="note-{ident}" class="review-note" data-for="{ident}" rows="2" placeholder="Your reasoning, question, or next step…"></textarea></div>
      </div></details></article>'''


def option_list(values):
    return ''.join(f'<option>{esc(v)}</option>' for v in values)


CHECKS = [(name, check) for name, report in D['reports'].items() for check in report['checks']]
check_rows = ''.join(f'<tr><td><b>{esc(c["name"])}</b><small>{esc(n)}</small></td><td><span class="result {"pass" if c["result"].lower().startswith("pass") else "observed-result"}">{esc(c["result"])}</span></td><td>{esc(c["detail"])}</td></tr>' for n, c in CHECKS)
strengths = ''.join('<details class="panel"><summary>' + esc(n.replace('-', ' ').title()) + ' · ' + str(len(r['strengths'])) + ' strengths</summary>' + paras(r['strengths']) + '</details>' for n, r in D['reports'].items())
limitations = ''.join('<details class="panel"><summary>' + esc(n.replace('-', ' ').title()) + ' · limits of this review</summary>' + paras(r['limitations']) + '</details>' for n, r in D['reports'].items())
inventory_rows = ''.join(f'<tr><td><code>{esc(i["file"])}</code></td><td>{esc(i["group"])}</td><td class="mono">{i["sha256"][:12]}</td></tr>' for i in D['inventory'])
input_rows = ''.join(f'<tr><td>{esc(i["layer"])}</td><td>{esc(i["name"])}</td><td><code>{esc(i["revision"][:12] or i["url"])}</code></td><td>{esc(i["modified"][:10] or "tarball pin")}</td></tr>' for i in D['inputs'])
extension_rows = ''.join(f'<tr><td>{esc(x["name"])}</td><td>{esc(", ".join(x["versions"]))}</td><td>{"Declared" if x["declares_shell_50"] else "Bypass in use"}</td><td>Active at snapshot</td></tr>' for x in D['extensions'])
AI = D['reports']['herdr-ai']['metrics']
SYS = D['reports']['system']['metrics']
E = D['reports']['editor-cli']['metrics']
WORK = D['cli_usage']['workflow_totals']
usage_recs = ''.join(f'<li><b>{esc(x["title"])}</b><p>{esc(x["detail"])}</p></li>' for x in D['cli_usage']['recommendations'])
ai_recs = ''.join(f'<li><b>{esc(x["title"])}</b><p>{esc(x["detail"])}</p></li>' for x in D['ai_usage']['recommendations'] if x['title'] != 'Reconsider blanket worktree trust')
methodology = paras(D['methodology'])

